<?php
use PHPUnit\Framework\TestCase;use ZinCelestial\Platform\Audit\ImmutableAuditLog;use ZinCelestial\Platform\Recovery\PersistentReplayTokenStore;
final class PersistenceAuditE2ETest extends TestCase{public function test_replay_jti_is_single_use_across_instances():void{global $wpdb;$table=$wpdb->base_prefix.'zcp_replay_tokens';$a=new PersistentReplayTokenStore($wpdb,$table,1);$a->consume('unique-jti',time()+300);$this->expectException(RuntimeException::class);(new PersistentReplayTokenStore($wpdb,$table,1))->consume('unique-jti',time()+300);}public function test_audit_chain_detects_tampering():void{global $wpdb;$table=$wpdb->base_prefix.'zcp_audit_log';$log=new ImmutableAuditLog($wpdb,$table,1);$log->append('policy_allowed',['policy'=>'p','result'=>'allow'],1);$rows=$wpdb->get_results("SELECT * FROM $table WHERE site_id=1 ORDER BY sequence_id",ARRAY_A);$this->assertTrue($log->verify($rows,fn()=>wp_salt('secure_auth')));$rows[0]['payload'].='x';$this->assertFalse($log->verify($rows,fn()=>wp_salt('secure_auth')));}public function test_other_tenant_data_is_not_returned():void{global $wpdb;$table=$wpdb->base_prefix.'zcp_audit_log';$rows=$wpdb->get_results($wpdb->prepare("SELECT site_id FROM $table WHERE site_id=%d",2),ARRAY_A);foreach($rows as $r)$this->assertSame('2',(string)$r['site_id']);}}
